T={(0,2),(1,1),(1,3),(2,0),(2,1),(2,3)}
objs={2:{(4,14),(5,13),(6,12)},8:{(2,24),(3,23),(4,23)},5:{(10,26),(11,25),(11,26)},6:{(12,6),(13,6),(13,8)},3:{(12,16),(13,17),(14,17)},7:{(20,12),(21,13)},9:{(23,6),(24,4)}}
def transforms(S):
 out=[]
 for k in range(4):
  for ref in [False,True]:
   pts=[]
   for r,c in S:
    if ref: c=-c
    for _ in range(k): r,c=c,-r
    pts.append((r,c))
   mr=min(r for r,c in pts);mc=min(c for r,c in pts)
   norm=frozenset((r-mr,c-mc) for r,c in pts)
   if norm not in [x[0] for x in out]: out.append((norm,k,ref))
 return out
for col,pts in objs.items():
 sol=[]
 for shape,k,ref in transforms(T):
  for pr,pc in pts:
   for sr,sc in shape:
    dr,dc=pr-sr,pc-sc
    if all((r-dr,c-dc) in shape for r,c in pts):
     sol.append((k,ref,dr,dc,sorted(shape)))
 sol2={(k,ref,dr,dc) for k,ref,dr,dc,_ in sol}
 print(col, len(sol2), sorted(sol2))

