A={(0,2),(0,3),(1,0),(1,1),(2,2)}
B={(0,1),(0,2),(0,3),(1,0),(1,4),(2,1),(3,1),(3,2)}
objs={4:{(3,7),(4,6),(4,8),(5,5),(5,6),(5,8)},2:{(3,13),(4,12),(5,11)},8:{(1,23),(2,22),(3,22)},5:{(9,25),(10,24),(10,25)},6:{(11,5),(12,5),(12,7)},3:{(11,15),(12,16),(13,16)},7:{(19,11),(20,12)},9:{(22,5),(23,3)}}
def vars(T):
 out=[]
 for k in range(4):
  for f in (False,True):
   pts=[]
   for r,c in T:
    if f:c=-c
    for _ in range(k):r,c=c,-r
    pts.append((r,c))
   mr=min(r for r,c in pts);mc=min(c for r,c in pts)
   P=frozenset((r-mr,c-mc) for r,c in pts)
   if P not in [v[2] for v in out]:out.append((k,f,P))
 return out
