def variants(T):
 out=[]
 for k in range(4):
  for f in (False,True):
   pts=[]
   for r,c in T:
    if f:c=-c
    for _ in range(k):r,c=c,-r
    pts.append((r,c))
   mr=min(r for r,c in pts);mc=min(c for r,c in pts)
   P=frozenset((r-mr,c-mc) for r,c in pts)
   if P not in [v[2] for v in out]:out.append((k,f,P))
 return out
