import json
R=C=30
T={(0,2),(1,1),(1,3),(2,0),(2,1),(2,3)}
source={4:{(3,7),(4,6),(4,8),(5,5),(5,6),(5,8)},2:{(3,13),(4,12),(5,11),(21,21),(21,22)},8:{(1,23),(2,22),(3,22)},5:{(9,25),(10,24),(10,25)},6:{(11,5),(12,5),(12,7)},3:{(11,15),(12,16),(13,16)},7:{(19,11),(20,12)},9:{(22,5),(23,3)}}
def variants(T):
 out=[]
 for k in range(4):
  for flip in (False,True):
   pts=[]
   for r,c in T:
    if flip:c=-c
    for _ in range(k):r,c=c,-r
    pts.append((r,c))
   mr=min(r for r,c in pts);mc=min(c for r,c in pts)
   P=frozenset((r-mr,c-mc) for r,c in pts)
   if P not in [q[2] for q in out]:out.append((k,flip,P))
 return out
allpts=set().union(*source.values())
for col,pts in source.items():
 if col==4:continue
 cand=[]
 for k,f,P in variants(T):
  for r,c in pts:
   for dr,dc in P:
    org=(r-dr,c-dc)
    cells={(org[0]+a,org[1]+b) for a,b in P}
    if pts <= cells and min(a for a,b in cells)>=0 and max(a for a,b in cells)<R and min(b for a,b in cells)>=0 and max(b for a,b in cells)<C and not ((cells & (allpts-pts))):
     cand.append((k,f,org,tuple(sorted(cells))))
 unique={(k,f,o):cells for k,f,o,cells in cand}
 print('\n',col,'valid',len(unique))
 for key,cells in unique.items(): print(key,cells)

